<?php
 namespace Pterodactyl\Models; use Illuminate\Support\Carbon; use Illuminate\Support\Collection; use Illuminate\Database\Eloquent\Model as IlluminateModel; use Illuminate\Database\Eloquent\Relations\BelongsTo; class ConsoleCommand extends IlluminateModel { public const KEEP = 200; public const KEEP_DAYS = 90; protected $table = 'console_commands'; protected $fillable = ['user_id', 'server_id', 'command']; protected $casts = [ 'user_id' => 'int', 'server_id' => 'int', ]; public function user(): BelongsTo { return $this->belongsTo(User::class); } public function server(): BelongsTo { return $this->belongsTo(Server::class); } public static function remember(int $userId, int $serverId, string $command): void { static::query() ->where('user_id', $userId) ->where('server_id', $serverId) ->where('command', $command) ->delete(); static::create([ 'user_id' => $userId, 'server_id' => $serverId, 'command' => $command, ]); static::prune($userId, $serverId); } public static function recent(int $userId, int $serverId): Collection { return static::query() ->where('user_id', $userId) ->where('server_id', $serverId) ->where('created_at', '>=', Carbon::now()->subDays(self::KEEP_DAYS)) ->orderByDesc('id') ->limit(self::KEEP) ->get(['id', 'command', 'created_at']) ->map(fn (self $entry) => [ 'id' => (int) $entry->id, 'command' => (string) $entry->command, 'at' => $entry->created_at?->toIso8601String(), ]); } private static function prune(int $userId, int $serverId): void { static::query() ->where('user_id', $userId) ->where('server_id', $serverId) ->where('created_at', '<', Carbon::now()->subDays(self::KEEP_DAYS)) ->delete(); $cutoff = static::query() ->where('user_id', $userId) ->where('server_id', $serverId) ->orderByDesc('id') ->offset(self::KEEP - 1) ->limit(1) ->value('id'); if ($cutoff === null) { return; } static::query() ->where('user_id', $userId) ->where('server_id', $serverId) ->where('id', '<', $cutoff) ->delete(); } } 